  Lemma asched_facts : forall LB m S ioc cfgb, AScheduler LB m S (mkSCH (sched_hdr ioc cfgb) 0 0 0) ->
    ro_cells asegs m S (SvcHdrCells (sched_hdr ioc cfgb)) /\ accessible m S 48 /\ aapp S 48 /\ S mod 16 = 0 /\ rblock_range S NEWSZ_SCH
    /\ (exists p, In (p, S, NEWSZ_SCH) LB).
  Proof.
    intros LB m S ioc cfgb SCH.
    pose proof SCH as (pS & j50 & jm & j109 & je & jt & j219 & j7 & INS & HDR & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & RBS & ADS).
    pose proof (rblock_bounds _ _ RBS) as (Q0 & QN & QTOP & QIMG & QHI & Q8). pose proof RBS as (_ & Q16 & _ & APS & _).
    split; [exact (proj1 HDR)|]. split; [| split; [| split; [exact Q16| split; [exact RBS| exists pS; exact INS]]]].
    - eapply addressable_accessible with (A := S) (n := NEWSZ_SCH); [exact ADS| lia| unfold NEWSZ_SCH; lia| unfold NEWSZ_SCH, AAPP_HI in *; lia].
    - eapply aapp_sub; [exact APS| lia| unfold NEWSZ_SCH; lia].
  Qed.
