  Lemma asched_chain_nomatch : forall ioc S cfgb, Forall (fun e => keys_match 0 AG_ID_SSVC 0 e = false) [sched_elt ioc S cfgb; cfg_elt ioc cfgb].
  Proof.
    intros. repeat apply Forall_cons; try apply Forall_nil; apply keys_match_false_intro; cbn; first [left; reflexivity | right; left; reflexivity].
  Qed.

  (* [comment removed for export] *)
  Lemma asched_chain_objs : forall LB m LF S ioc cfgb regb,
    AScheduler LB m S (mkSCH (sched_hdr ioc cfgb) 0 0 0) -> AConfigSvc LB m cfgb (cfg_hdr ioc) ->
    (S + 48 <= regb \/ regb + SZ_REG <= S) -> (cfgb + 48 <= regb \/ regb + SZ_REG <= cfgb) ->
    Forall (fun e => aobj LB LF (se_addr e) 48 /\ (se_addr e + 48 <= regb \/ regb + SZ_REG <= se_addr e) /\ ati_client e) [sched_elt ioc S cfgb; cfg_elt ioc cfgb].
  Proof.
    intros LB m LF S ioc cfgb regb SCH CFG SEP1 SEP2.
    pose proof (asched_facts _ _ _ _ _ SCH) as (_ & _ & _ & _ & _ & [pS INS]). pose proof CFG as (pC & _ & _ & INC & _).
    apply Forall_cons; [| apply Forall_cons; [| apply Forall_nil]]; cbn [se_addr se_hdr sched_elt cfg_elt].
    - split; [eapply aobj_block; [exact INS| lia| unfold NEWSZ_SCH; lia]|]. split; [exact SEP1|].
      unfold ati_client, sched_elt. cbn [se_hdr sched_hdr sv_ti]. unfold AL_TYPEID_SCHED. intros _. lia.
    - split; [eapply aobj_block; [exact INC| lia| unfold NEWSZ_CFG; lia]|]. split; [exact SEP2|].
      unfold ati_client, cfg_elt. cbn [se_hdr cfg_hdr sv_ti]. unfold AL_TYPEID_CONFIG. intros _. lia.
  Qed.

End HCW.
